export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.88, 0.82, 0.82);
  scene.useRightHandedSystem = true;

  const camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0.07, 1.14, 0.06));
  camera.alpha = 1.8;
  camera.beta = 1.6;
  camera.radius = 4.8;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.zoomToMouseLocation = true;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);

  const box = BABYLON.MeshBuilder.CreateBox("box", {}, scene);
  box.rotationQuaternion = null;
  box.rotation = new BABYLON.Vector3(0, 0, 0);
  box.computeWorldMatrix(true);
  const boxMat = new BABYLON.StandardMaterial("boxMat", scene);
  boxMat.diffuseColor = BABYLON.Color3.FromHexString("#333333");
  box.material = boxMat;

  var sphere = BABYLON.MeshBuilder.CreateSphere("sphere", { diameter: 1 }, scene);
  sphere.position = new BABYLON.Vector3(1.5, 1, 0);
  const sphereeMat = new BABYLON.StandardMaterial("sphereMat", scene);
  sphereeMat.diffuseColor = BABYLON.Color3.FromHexString("#aefbbd");
  sphere.material = sphereeMat;

  const initialStates = new Map();
  initialStates.set(box, {
    scaling: box.scaling.clone(),
    position: box.position.clone(),
    rotation: box.rotation.clone(),
    material: box.material.clone("boxMatClone"),
  });

  initialStates.set(sphere, {
    scaling: sphere.scaling.clone(),
    position: sphere.position.clone(),
    rotation: sphere.rotation.clone(),
    material: sphere.material.clone("sphereMatClone"),
  });

  let selectedMesh = box;

  const gui = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

  const rootRect = new BABYLON.GUI.Rectangle("root");
  rootRect.width = "240px";
  rootRect.height = "auto";
  rootRect.adaptHeightToChildren = true;
  rootRect.thickness = 0;
  rootRect.background = "#222129";
  rootRect.cornerRadius = 10;
  rootRect.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  rootRect.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  rootRect.leftInPixels = 20;
  rootRect.topInPixels = 30;
  gui.addControl(rootRect);
  rootRect.onPointerEnterObservable.add(() => {
    document.body.style.cursor = "pointer";
  });

  const explaintText = new BABYLON.GUI.TextBlock("Explain Text");
  explaintText.text = "Draggable ↓";
  explaintText.height = "30px";
  explaintText.color = "Black";
  explaintText.fontSize = 20;
  explaintText.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  explaintText.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  explaintText.leftInPixels = 20;
  explaintText.topInPixels = 0;
  explaintText.leftInPixels = 90;
  explaintText.topInPixels = 0;
  gui.addControl(explaintText);

  let isDragging = false;
  let dragOffsetX = 0;
  let dragOffsetY = 0;

  rootRect.onPointerDownObservable.add(() => {
    isDragging = true;
    document.body.style.cursor = "grabbing";
    dragOffsetX = scene.pointerX - rootRect._currentMeasure.left;
    dragOffsetY = scene.pointerY - rootRect._currentMeasure.top;

    camera.detachControl();
  });

  scene.onPointerObservable.add((pointerInfo) => {
    if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERPICK) {
      const picked = pointerInfo.pickInfo?.pickedMesh;
      if (picked && (picked === box || picked === sphere)) {
        updateGUIFromMesh(picked);
      }
    }

    if (!isDragging) return;

    if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERMOVE) {
      const dtw = gui.getSize().width;
      const dth = gui.getSize().height;

      const rectWidth = rootRect._currentMeasure.width;
      const rectHeight = rootRect._currentMeasure.height;
      const explainHeight = explaintText._currentMeasure.height;

      let newLeft = scene.pointerX - dragOffsetX;
      let newTop = scene.pointerY - dragOffsetY;

      newLeft = Math.min(Math.max(0, newLeft), dtw - rectWidth);
      newTop = Math.min(Math.max(explainHeight, newTop), dth - rectHeight);

      rootRect.leftInPixels = newLeft;
      rootRect.topInPixels = newTop;
      explaintText.leftInPixels = newLeft + 70;
      explaintText.topInPixels = newTop - 30;
    }

    if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERUP) {
      isDragging = false;
      document.body.style.cursor = "default";
      camera.attachControl(canvas, true);
    }
  });

  const panel = new BABYLON.GUI.StackPanel("Root StackPanel");
  panel.width = 1;
  panel.paddingLeft = "10px";
  panel.paddingRight = "10px";
  panel.spacing = 6;
  panel.paddingTop = "6px";
  panel.paddingBottom = "6px";
  rootRect.addControl(panel);

  const header = new BABYLON.GUI.TextBlock("Mesh Name Header");
  header.text = "Box";
  header.height = "30px";
  header.color = "white";
  header.fontSize = 20;
  header.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  panel.addControl(header);

  const sectionContainer = (children) => {
    const rect = new BABYLON.GUI.Rectangle("sectionContainer Rectangle");
    rect.color = "#444";
    rect.thickness = 1;
    rect.cornerRadius = 6;
    rect.background = "#353541";
    rect.paddingRight = "6px";
    rect.adaptHeightToChildren = true;
    rect.width = 1;

    const stack = new BABYLON.GUI.StackPanel("sectionContainer StackPanel");
    stack.width = 1;
    stack.paddingTop = "6px";
    stack.paddingBottom = "6px";
    stack.paddingRight = "6px";
    stack.spacing = 4;

    children.forEach((c) => stack.addControl(c));
    rect.addControl(stack);
    return rect;
  };

  const sectionLabel = (text) => {
    const label = new BABYLON.GUI.TextBlock("sectionLabel Text");
    label.text = text;
    label.color = "#cecece";
    label.fontSize = 14;
    label.height = "20px";
    label.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    label.paddingLeft = "6px";
    return label;
  };

  // Transform section
  const posGrid = new BABYLON.GUI.Grid("Pos Grid");
  posGrid.addColumnDefinition(0.15);
  posGrid.addColumnDefinition(0.28);
  posGrid.addColumnDefinition(0.15);
  posGrid.addColumnDefinition(0.28);
  posGrid.addColumnDefinition(0.15);
  posGrid.addColumnDefinition(0.28);
  posGrid.height = "30px";
  posGrid.width = 1;
  posGrid.paddingRight = "6px";

  const posLabel = new BABYLON.GUI.TextBlock("Pos Label");
  posLabel.text = "position";
  posLabel.color = "#cecece";
  posLabel.fontSize = 13;
  posLabel.height = "20px";
  posLabel.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  posLabel.paddingLeft = "6px";

  const posLabels = ["X", "Y", "Z"];
  const posInputs = [];

  posLabels.forEach((axis, i) => {
    const label = new BABYLON.GUI.TextBlock("PosLabel Text");
    label.text = axis;
    label.color = "#cecece";
    label.fontSize = 13;
    label.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_CENTER;
    posGrid.addControl(label, 0, i * 2);

    const input = new BABYLON.GUI.InputText("PosLabel Input");
    input.text = "0.00";
    input.width = "100%";
    input.height = "25px";
    input.color = "white";
    input.background = "#2a2a2a";
    input.focusedBackground = "#333";
    input.highlightColor = "#2196F3";
    input.fontSize = 13;
    posGrid.addControl(input, 0, i * 2 + 1);
    posInputs.push(input);
  });

  posInputs.forEach((input) => {
    input.onBlurObservable.add(() => {
      if (!selectedMesh) return;
      const x = parseFloat(posInputs[0].text) || 0;
      const y = parseFloat(posInputs[1].text) || 0;
      const z = parseFloat(posInputs[2].text) || 0;
      selectedMesh.position.set(x, y, z);
    });
  });

  const rotGrid = new BABYLON.GUI.Grid("Rot Grid");
  rotGrid.addColumnDefinition(0.15);
  rotGrid.addColumnDefinition(0.28);
  rotGrid.addColumnDefinition(0.15);
  rotGrid.addColumnDefinition(0.28);
  rotGrid.addColumnDefinition(0.15);
  rotGrid.addColumnDefinition(0.28);
  rotGrid.height = "30px";
  rotGrid.width = 1;

  const rotLabel = new BABYLON.GUI.TextBlock("Rot Label");
  rotLabel.text = "rotation";
  rotLabel.color = "#cecece";
  rotLabel.fontSize = 13;
  rotLabel.height = "20px";
  rotLabel.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  rotLabel.paddingLeft = "6px";

  const rotStackPanel = new BABYLON.GUI.StackPanel("Rot StackPanel");
  rotStackPanel.width = 1;
  rotStackPanel.spacing = 4;

  const rotLabels = ["X", "Y", "Z"];
  const rotSliders = [];

  rotLabels.forEach((axis, i) => {
    const stack = new BABYLON.GUI.StackPanel("rotLabels StackPanel");
    stack.width = "90%";
    stack.height = "30px";
    stack.isVertical = false;
    stack.spacing = 6;

    const label = new BABYLON.GUI.TextBlock("rotLabels label Text");
    label.text = axis;
    label.width = "24px";
    label.color = "#cecece";
    label.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    label.paddingLeft = "2px";
    label.fontSize = 13;

    const slider = new BABYLON.GUI.Slider("rotLabels Slider");
    slider.minimum = 0;
    slider.maximum = 360;
    slider.step = 1;
    slider.height = "20px";
    slider.width = "120px";
    slider.color = "#2196F3";
    slider.background = "#111";
    slider.thumbColor = "#2196F3";

    const valueText = new BABYLON.GUI.TextBlock("rotLabels value Text");
    valueText.text = "0°";
    valueText.width = "38px";
    valueText.color = "#cecece";
    valueText.fontSize = 13;

    slider.onValueChangedObservable.add((v) => {
      if (!selectedMesh || selectedMesh.rotationQuaternion) return;

      const x = BABYLON.Tools.ToRadians(rotSliders[0].slider.value % 360);
      const y = BABYLON.Tools.ToRadians(rotSliders[1].slider.value % 360);
      const z = BABYLON.Tools.ToRadians(rotSliders[2].slider.value % 360);

      selectedMesh.rotation.set(x, y, z);
      valueText.text = `${v.toFixed(0)}°`;
    });

    stack.addControl(label);
    stack.addControl(slider);
    stack.addControl(valueText);

    rotStackPanel.addControl(stack);
    rotSliders.push({ slider, valueText });
  });

  const scaleGrid = new BABYLON.GUI.Grid("Scale Grid");
  scaleGrid.addColumnDefinition(0.15);
  scaleGrid.addColumnDefinition(0.28);
  scaleGrid.addColumnDefinition(0.15);
  scaleGrid.addColumnDefinition(0.28);
  scaleGrid.addColumnDefinition(0.15);
  scaleGrid.addColumnDefinition(0.28);
  scaleGrid.height = "30px";
  scaleGrid.width = 1;
  scaleGrid.paddingRight = "6px";

  const scaleLabel = new BABYLON.GUI.TextBlock("Scale Text");
  scaleLabel.text = "scale";
  scaleLabel.color = "#cecece";
  scaleLabel.fontSize = 13;
  scaleLabel.height = "20px";
  scaleLabel.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  scaleLabel.paddingLeft = "6px";

  const scaleLabels = ["X", "Y", "Z"];
  const scaleInputs = [];

  scaleLabels.forEach((axis, i) => {
    const label = new BABYLON.GUI.TextBlock("scaleLabels Text");
    label.text = axis;
    label.color = "#cecece";
    label.fontSize = 13;
    label.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_CENTER;
    scaleGrid.addControl(label, 0, i * 2);

    const input = new BABYLON.GUI.InputText("scaleLabels Input");
    input.text = "1.00";
    input.width = "100%";
    input.height = "25px";
    input.color = "white";
    input.background = "#2a2a2a";
    input.focusedBackground = "#333";
    input.highlightColor = "#2196F3";
    input.fontSize = 13;
    scaleGrid.addControl(input, 0, i * 2 + 1);
    scaleInputs.push(input);
  });

  scaleInputs.forEach((input) => {
    input.onBlurObservable.add(() => {
      if (!selectedMesh) return;
      const x = parseFloat(scaleInputs[0].text) || 1;
      const y = parseFloat(scaleInputs[1].text) || 1;
      const z = parseFloat(scaleInputs[2].text) || 1;
      selectedMesh.scaling.set(x, y, z);
    });
  });

  const transformGroup = sectionContainer([sectionLabel("Transform"), posLabel, posGrid, rotLabel, rotStackPanel, scaleLabel, scaleGrid]);

  panel.addControl(transformGroup);

  // Material section
  const colorGrid = new BABYLON.GUI.Grid("Color Grid");
  colorGrid.addColumnDefinition(0.3);
  colorGrid.addColumnDefinition(0.7);
  colorGrid.height = "30px";
  colorGrid.width = 1;
  colorGrid.hoverCursor = "pointer";

  const colorBox = new BABYLON.GUI.Ellipse("Color Ellipse");
  colorBox.width = "24px";
  colorBox.height = "24px";
  colorBox.color = "white";
  colorBox.thickness = 2;
  colorBox.background = "#333333";
  colorBox.hoverCursor = "pointer";
  colorGrid.addControl(colorBox, 0, 0);
  colorBox.onPointerClickObservable.add(() => {
    navigator.clipboard
      .writeText(colorText.background)
      .then(() => {
        showToast(`${colorText.text} Copied to clipboard!`);
      })
      .catch(() => {
        showToast("Copy failed");
      });
  });

  const colorText = new BABYLON.GUI.TextBlock("Color Text");
  colorText.text = "#333333";
  colorText.color = "white";
  colorText.fontSize = 13;
  colorText.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  colorText.paddingLeft = "10px";
  colorText.hoverCursor = "pointer";
  colorGrid.addControl(colorText, 0, 1);

  colorText.onPointerClickObservable.add(() => {
    navigator.clipboard
      .writeText(colorText.text)
      .then(() => {
        showToast(`${colorText.text} Copied to clipboard!`);
      })
      .catch(() => {
        showToast("Copy failed");
      });
  });

  const picker = new BABYLON.GUI.ColorPicker("ColorPicker");
  picker.value = BABYLON.Color3.FromHexString("#333333");
  picker.height = "120px";
  picker.width = "120px";
  picker.onValueChangedObservable.add((v) => {
    if (!selectedMesh || !selectedMesh.material) return;
    selectedMesh.material.diffuseColor = v.clone();
    colorBox.background = v.toHexString();
    colorText.text = v.toHexString();
  });

  const checkGrid = new BABYLON.GUI.Grid("Wireframe Grid");
  checkGrid.addColumnDefinition(0.3);
  checkGrid.addColumnDefinition(0.7);
  checkGrid.height = "30px";
  checkGrid.width = 1;

  const check = new BABYLON.GUI.Checkbox("Wireframe Checkbox");
  check.width = "20px";
  check.height = "20px";
  check.color = "#2196F3";
  check.background = "#2a2a2a";

  check.onIsCheckedChangedObservable.add((v) => {
    if (!selectedMesh || !selectedMesh.material) return;
    selectedMesh.material.wireframe = v;
  });

  const label = new BABYLON.GUI.TextBlock("Wireframe Text ");
  label.text = "wireframe";
  label.color = "white";
  label.fontSize = 14;
  label.height = "20px";
  label.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  label.paddingLeft = "10px";

  checkGrid.addControl(check, 0, 0);
  checkGrid.addControl(label, 0, 1);

  const materialGroup = sectionContainer([sectionLabel("Material"), colorGrid, picker, checkGrid]);
  panel.addControl(materialGroup);

  const reset = BABYLON.GUI.Button.CreateSimpleButton("Reset", "reset");
  reset.width = 1;
  reset.height = "30px";
  reset.color = "white";
  reset.thickness = 0;
  reset.background = "#2196F3";
  reset.cornerRadius = 8;
  reset.paddingTop = "10px";

  reset.onPointerUpObservable.add(() => {
    if (!selectedMesh) return;

    const init = initialStates.get(selectedMesh);
    if (!init) return;

    selectedMesh.position.copyFrom(init.position);
    selectedMesh.rotationQuaternion = null;
    selectedMesh.rotation.copyFrom(init.rotation);
    selectedMesh.scaling.copyFrom(init.scaling);
    selectedMesh.computeWorldMatrix(true);

    selectedMesh.material = init.material.clone("resetMat_" + selectedMesh.name);

    posInputs[0].text = init.position.x.toFixed(2);
    posInputs[1].text = init.position.y.toFixed(2);
    posInputs[2].text = init.position.z.toFixed(2);

    scaleInputs[0].text = init.scaling.x.toFixed(2);
    scaleInputs[1].text = init.scaling.y.toFixed(2);
    scaleInputs[2].text = init.scaling.z.toFixed(2);

    if (!selectedMesh.rotationQuaternion) {
      const rx = (BABYLON.Tools.ToDegrees(init.rotation.x) + 360) % 360;
      const ry = (BABYLON.Tools.ToDegrees(init.rotation.y) + 360) % 360;
      const rz = (BABYLON.Tools.ToDegrees(init.rotation.z) + 360) % 360;

      rotSliders[0].slider.value = rx;
      rotSliders[1].slider.value = ry;
      rotSliders[2].slider.value = rz;

      rotSliders[0].valueText.text = `${rx.toFixed(0)}°`;
      rotSliders[1].valueText.text = `${ry.toFixed(0)}°`;
      rotSliders[2].valueText.text = `${rz.toFixed(0)}°`;
    }

    const color = init.material.diffuseColor.clone();
    picker.value = color;
    colorBox.background = color.toHexString();
    colorText.text = color.toHexString();

    check.isChecked = init.material.wireframe || false;
  });

  panel.addControl(reset);

  const updateGUIFromMesh = (mesh) => {
    if (!mesh) return;

    selectedMesh = mesh;
    header.text = mesh.name;

    const p = mesh.position;
    posInputs[0].text = p.x.toFixed(2);
    posInputs[1].text = p.y.toFixed(2);
    posInputs[2].text = p.z.toFixed(2);

    scaleInputs[0].text = mesh.scaling.x.toFixed(2);
    scaleInputs[1].text = mesh.scaling.y.toFixed(2);
    scaleInputs[2].text = mesh.scaling.z.toFixed(2);

    if (!mesh.rotationQuaternion) {
      const rot = mesh.rotation;
      const deg = [
        (BABYLON.Tools.ToDegrees(rot.x) + 360) % 360,
        (BABYLON.Tools.ToDegrees(rot.y) + 360) % 360,
        (BABYLON.Tools.ToDegrees(rot.z) + 360) % 360,
      ];

      rotSliders.forEach(({ slider, valueText }, i) => {
        slider.value = deg[i];
        valueText.text = `${deg[i].toFixed(0)}°`;
      });
    }

    if (mesh.material && mesh.material.diffuseColor) {
      const color = mesh.material.diffuseColor;
      picker.value = color.clone();
      colorBox.background = color.toHexString();
      colorText.text = color.toHexString();
      check.isChecked = mesh.material.wireframe || false;
    }
  };

  updateGUIFromMesh(box);

  const showToast = (message) => {
    const toastRect = new BABYLON.GUI.Rectangle();
    toastRect.width = "220px";
    toastRect.height = "36px";
    toastRect.thickness = 0;
    toastRect.background = "#000000cc";
    toastRect.alpha = 0;
    toastRect.cornerRadius = 8;
    toastRect.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_CENTER;
    toastRect.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
    toastRect.topInPixels = -40;

    const toastText = new BABYLON.GUI.TextBlock();
    toastText.text = message;
    toastText.color = "white";
    toastText.fontSize = 14;
    toastText.paddingLeft = "12px";
    toastText.paddingRight = "12px";

    toastRect.addControl(toastText);
    gui.addControl(toastRect);

    const inSpeed = 6;
    const outSpeed = 3;
    const waitFrames = 60;

    let frame = 0;
    let phase = "in";

    const observer = scene.onBeforeRenderObservable.add(() => {
      if (phase === "in") {
        toastRect.topInPixels += inSpeed;
        toastRect.alpha += 0.1;
        if (toastRect.topInPixels >= 20) {
          toastRect.topInPixels = 20;
          toastRect.alpha = 1;
          phase = "wait";
          frame = 0;
        }
      } else if (phase === "wait") {
        frame++;
        if (frame > waitFrames) phase = "out";
      } else if (phase === "out") {
        toastRect.topInPixels -= outSpeed;
        toastRect.alpha = Math.max(0, toastRect.alpha - 0.05);

        if (toastRect.alpha <= 0.01) {
          gui.removeControl(toastRect);
          scene.onBeforeRenderObservable.remove(observer);
        }
      }
    });
  };

  return scene;
}
